/* finds an occupied slot with an unset key in the requested order (joined with Map_FindUnsetKeySlot_loop_tail) */
int Map_FindUnsetKeySlot(int reverse) {
    int i = 0;
    int *base = map_menu_state_key_slots;
    int *keys = base + 5;
    do {
        int slot = reverse ? 4 - i : i;
        if (base[slot] && keys[slot] == -1)
            return slot;
        ++i;
    } while (i < 5);
    return -1;
}
